221:             KHR_ICD_TRACE("failed to allocate memory\n");
222:             free(vendor);
223:             continue;
224:         }
225:         result = KHR_ICD2_DISPATCH(platforms[i])->clGetPlatformInfo(
226:             platforms[i],
227:             CL_PLATFORM_EXTENSIONS,
228:             extensionsSize,
229:             extensions,
230:             NULL);
231:         if (CL_SUCCESS != result)
232:         {
233:             KHR_ICD_TRACE("failed query platform extensions\n");
234:             free(extensions);
235:             free(vendor);
236:             continue;
237:         }
238: 
239:         if (strstr(extensions, "cl_khr_icd_unloadable"))
240:         {
241:             KHR_ICD_TRACE("found cl_khr_icd_unloadable extension support\n");
242:             free(extensions);
243:             result = KHR_ICD2_DISPATCH(platforms[i])->clGetPlatformInfo(
244:                 platforms[i],
245:                 CL_PLATFORM_UNLOADABLE_KHR,
246:                 sizeof(vendor->unloadable),
247:                 &vendor->unloadable,
248:                 NULL);
249:             if (vendor->unloadable)
250:             {
251:                 KHR_ICD_TRACE("platform is unloadable\n");
252:             }
253:             if (CL_SUCCESS != result)
254:             {
255:                 KHR_ICD_TRACE("found cl_khr_icd_unloadable but clGetPlatformInfo CL_PLATFORM_UNLOADABLE_KHR query failed\n");
256:                 free(vendor);
257:                 continue;
258:             }
259:         }
260: 
261:         // call clGetPlatformInfo on the returned platform to get the suffix
262:         result = KHR_ICD2_DISPATCH(platforms[i])->clGetPlatformInfo(
263:             platforms[i],
264:             CL_PLATFORM_ICD_SUFFIX_KHR,
265:             0,
266:             NULL,
267:             &suffixSize);
268:         if (CL_SUCCESS != result)
269:         {
270:             KHR_ICD_TRACE("failed query platform ICD suffix\n");
271:             free(vendor);
272:             continue;
273:         }
274:         suffix = (char *)malloc(suffixSize);
275:         if (!suffix)
276:         {
277:             KHR_ICD_TRACE("failed to allocate memory\n");
278:             free(vendor);
279:             continue;
280:         }
281:         result = KHR_ICD2_DISPATCH(platforms[i])->clGetPlatformInfo(
282:             platforms[i],
283:             CL_PLATFORM_ICD_SUFFIX_KHR,
284:             suffixSize,
285:             suffix,
286:             NULL);
287:         if (CL_SUCCESS != result)
288:         {
289:             KHR_ICD_TRACE("failed query platform ICD suffix\n");
290:             free(suffix);
291:             free(vendor);
292:             continue;
293:         }
