27: #define STATUS_SUCCESS  ((NTSTATUS)0x00000000L)
28: #define STATUS_BUFFER_TOO_SMALL ((NTSTATUS)0xC0000023)
29: #define NT_SUCCESS(status) (((NTSTATUS)(status)) >= 0)
