24: char *khrIcd_getenv(const char *name) {
25:     char *retVal;
26:     DWORD valSize;
27: 
28:     valSize = GetEnvironmentVariableA(name, NULL, 0);
29: 
30:     // valSize DOES include the null terminator, so for any set variable
31:     // will always be at least 1. If it's 0, the variable wasn't set.
32:     if (valSize == 0) return NULL;
33: 
34:     // Allocate the space necessary for the registry entry
35:     retVal = (char *)malloc(valSize);
36: 
37:     if (NULL != retVal) {
38:         GetEnvironmentVariableA(name, retVal, valSize);
39:     }
40: 
41:     return retVal;
42: }
43: 
44: static bool khrIcd_IsHighIntegrityLevel()
45: {
46:     bool isHighIntegrityLevel = false;
47: 
48:     HANDLE processToken;
49:     if (OpenProcessToken(GetCurrentProcess(), TOKEN_QUERY | TOKEN_QUERY_SOURCE, &processToken)) {
50:         // Maximum possible size of SID_AND_ATTRIBUTES is maximum size of a SID + size of attributes DWORD.
51:         char mandatoryLabelBuffer[SECURITY_MAX_SID_SIZE + sizeof(DWORD)] = {0};
52:         DWORD bufferSize;
53:         if (GetTokenInformation(processToken, TokenIntegrityLevel, mandatoryLabelBuffer, sizeof(mandatoryLabelBuffer),
54:                                 &bufferSize) != 0) {
55:             const TOKEN_MANDATORY_LABEL* mandatoryLabel = (const TOKEN_MANDATORY_LABEL*)(mandatoryLabelBuffer);
56:             const DWORD subAuthorityCount = *GetSidSubAuthorityCount(mandatoryLabel->Label.Sid);
57:             const DWORD integrityLevel = *GetSidSubAuthority(mandatoryLabel->Label.Sid, subAuthorityCount - 1);
58: 
59:             isHighIntegrityLevel = integrityLevel > SECURITY_MANDATORY_MEDIUM_RID;
60:         }
61: 
62:         CloseHandle(processToken);
63:     }
64: 
65:     return isHighIntegrityLevel;
66: }
67: 
68: char *khrIcd_secure_getenv(const char *name) {
69:     if (khrIcd_IsHighIntegrityLevel()) {
70:         KHR_ICD_TRACE("Running at a high integrity level, so secure_getenv is returning NULL\n");
71:         return NULL;
72:     }
73: 
74:     return khrIcd_getenv(name);
75: }
